import ast
import operator


def eval_expression(expr):
    """
    +, -, *, / と括弧を含む算術式を計算する。
    数値は整数・浮動小数点数に対応。
    """

    tree = ast.parse(expr, mode="eval")

    binary_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
    }

    unary_operators = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def evaluate(node):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, bool) or not isinstance(
                node.value, (int, float)
            ):
                raise ValueError("数値以外は使用できません")
            return node.value

        if isinstance(node, ast.BinOp):
            op = binary_operators.get(type(node.op))
            if op is None:
                raise ValueError("使用できない演算子です")

            left = evaluate(node.left)
            right = evaluate(node.right)

            if isinstance(node.op, ast.Div) and right == 0:
                raise ZeroDivisionError("ゼロで割ることはできません")

            return op(left, right)

        if isinstance(node, ast.UnaryOp):
            op = unary_operators.get(type(node.op))
            if op is None:
                raise ValueError("使用できない単項演算子です")
            return op(evaluate(node.operand))

        raise ValueError("不正な式です")

    return evaluate(tree.body)
```

使用例:

```python
print(eval_expression("3 + 4 * (2 - 1)"))  # 7
print(eval_expression("-3 + 2 * 5"))       # 7
print(eval_expression("10 / (2 + 3)"))     # 2.0

try:
    eval_expression("1 / 0")
except ZeroDivisionError:
    print("ゼロ除算です")
```

`eval()` は使用せず、`ast` で許可した演算だけを処理しています。

